/**
 * Which paths are AQE's irreplaceable learning data.
 *
 * Pure: no `$`. Shared by the guard (hooks/guard.ts), the `/aqe-mod fleet`
 * verb and the tests.
 *
 * Protected, case-insensitively, anywhere in a path:
 * - the `.agentic-qe` directory itself (deleting or moving it loses everything),
 *   including a glob component that could match it (`.agentic*`, `.[a]gentic-qe`, `.*`);
 * - a direct child of `.agentic-qe/` named `*.db`, `*.db-wal`, `*.db-shm`,
 *   `*.db-journal` or `*.rvf` (memory.db and its WAL/SHM, brain/pattern stores);
 * - a glob directly under `.agentic-qe/` that could match one of those.
 *
 * Not protected: backups (`memory.db.bak-<ts>` does not end in `.db`, and a
 * name containing `backup` or a `.bak`/`-bak` part is a copy, not the store),
 * subdirectories (`.agentic-qe/agents/`), config, logs.
 *
 * Every `.agentic-qe` is protected wherever it lives, `/tmp/...` included: a
 * pure check cannot resolve globs, `$`-expansions or symlinks, so it cannot
 * tell a throwaway fixture from a project that lives under a temp directory.
 */
import { globMatch } from './glob'

/** A learning-data file's name: what the CLAUDE.md Data Protection rule guards. */
export const DATA_FILE = /\.(db(-wal|-shm|-journal)?|rvf)$/i

/** A backup's name (`memory-backup-20261009.db`, `memory.bak.db`, `x-bak-1.db`): a copy the guard lets tools write and remove. */
export const BACKUP_NAME = /backup|(^|[._-])bak([._-]|\d|$)/i

/** Names a glob is tried against to decide whether it could reach learning data. */
const SAMPLES = ['memory.db', 'memory.db-wal', 'memory.db-shm', 'memory.db-journal', 'brain.rvf', 'patterns.rvf', 'x.db']

const AQE = '.agentic-qe'

export type ProtectedKind = 'dir' | 'file' | 'glob'

/** The longest word read as a path; a longer one is judged by whether it mentions the store at all. */
export const MAX_PATH = 4096

/**
 * Collapses `\`, `//`, `/./`, `a/../` and a leading `./`, so `.agentic-qe/./memory.db`,
 * `x/../.agentic-qe/memory.db` and `./memory.db` read plainly. `./` alone reads as `.`.
 */
export function normalisePath(raw: string): string {
  const p = raw.replace(/\\/g, '/').replace(/\/{2,}/g, '/')
  const parts: string[] = []
  for (const part of p.split('/')) {
    if (part === '.' && parts.length > 0) continue
    if (part === '..' && parts.length > 0 && parts[parts.length - 1] !== '..' && parts[parts.length - 1] !== '' && parts[parts.length - 1] !== '.') {
      parts.pop()
      continue
    }
    parts.push(part)
  }
  while (parts.length > 1 && parts[0] === '.') parts.shift()
  const out = parts.join('/')
  return out === '' && p.startsWith('.') ? '.' : out
}

export const hasGlob = (s: string): boolean => /[*?[]/.test(s)

/** Whether a glob matches a name (linear; see glob.ts). */
export const globMatches = (glob: string, name: string): boolean => globMatch(glob, name)

/** Whether a glob (a file-name pattern, no directory part) could match a learning-data file. */
export const globReachesData = (glob: string): boolean => SAMPLES.some(name => globMatches(glob, name))

/**
 * Whether one path component names the `.agentic-qe` directory: literally (after
 * a `--db=` or `file:` style prefix), or as a glob the shell would expand to it.
 * A glob only reaches a dot-directory when it starts with `.` or a bracket.
 */
function namesAqe(component: string, dotglob: boolean): boolean {
  // A `--db=` or `file:` prefix, never one reaching into a glob (`.agentic-q[[:alpha:]]`).
  const c = component.replace(/^[^*?[]*[=:]/, '')
  if (c.toLowerCase() === AQE) return true
  // Leading `*`s are often an unknown expansion that may be empty (`"$X.agentic-qe"`, `$(true).agentic-qe`).
  if (/^\*+\./.test(c) && globMatches(c.replace(/^\*+/, ''), AQE)) return true
  return hasGlob(c) && (dotglob || c.startsWith('.') || c.startsWith('[')) && globMatches(c, AQE)
}

/** The index of the first component naming `.agentic-qe`, or -1. */
const aqeIndex = (parts: readonly string[], dotglob = false): number => parts.findIndex(p => namesAqe(p, dotglob))

/**
 * How a path touches learning data, or undefined when it does not.
 * `inAqe`: the command already changed into `.agentic-qe`, so a bare `memory.db` is the store.
 * `dotglob`: the line may have set `shopt -s dotglob`/`GLOBIGNORE`, so `*` also matches dot names.
 */
export function protectedKind(raw: string, inAqe = false, dotglob = false): ProtectedKind | undefined {
  // Outside `.agentic-qe`, a path can only reach it by naming it or by a glob: a cheap exit for every other word.
  if (!inAqe && !/agentic|[*?[]/i.test(raw)) return undefined
  // No real path is this long: read it as a glob that may reach the store when it could name it.
  if (raw.length > MAX_PATH) return inAqe || /agentic/i.test(raw) ? 'glob' : undefined
  const path = normalisePath(stripUri(raw.trim()))
  if (path === '') return undefined
  const parts = path.split('/')
  const at = aqeIndex(parts, dotglob)
  let rest: string
  if (at === -1) {
    if (!inAqe || path.includes('/')) return undefined
    rest = path
  } else {
    rest = parts.slice(at + 1).join('/')
  }
  if (rest === '' || rest === '.') return 'dir'
  // Only direct children are the stores; `.agentic-qe/agents/x.db` is someone's fixture.
  if (rest.includes('/')) return undefined
  if (hasGlob(rest)) return globReachesData(rest) ? 'glob' : undefined
  return DATA_FILE.test(rest) && !BACKUP_NAME.test(rest) ? 'file' : undefined
}

/** A `file:` URI's path without its `?query`/`#fragment` (`file:.agentic-qe/memory.db?mode=rw`). */
export const stripUri = (raw: string): string => (/^file:/i.test(raw) ? raw.replace(/[?#].*$/s, '') : raw)

/** The last path component. */
export const baseName = (p: string): string => {
  if (!/[\\/]/.test(p)) return p
  const parts = normalisePath(p).split('/').filter(s => s !== '')
  return parts[parts.length - 1] ?? ''
}

/** True when a path names something under `.agentic-qe` at any depth (for `find` roots and `rsync --delete`). */
export const underAqe = (raw: string, inAqe = false): boolean =>
  aqeIndex(normalisePath(raw.trim()).split('/')) !== -1 || (inAqe && (raw === '.' || raw === './' || !raw.startsWith('/')))

files.hooks/context.ts:
/**
 * What the guard knows while it reads one command line: where the command has
 * changed into, the variables it has set, the project root, and how to judge a
 * nested shell command. Pure: no `$`.
 */
import { MAX_PATH, protectedKind, type ProtectedKind } from './paths'
import { expandBraces, unmask, type Segment } from './shell'

/** Where the guard is judging: the project root, when the session knows it (so `find /abs/root ...` is read as from above `.agentic-qe`). */
export type GuardScope = { readonly root?: string }

export type Ctx = {
  /** The command has changed into `.agentic-qe` (`cd .agentic-qe`, `git -C .agentic-qe`). */
  inAqe: boolean
  /** Some word of the whole line names learning data (for `xargs rm`, `| sh`, `while read`). */
  mentionsData: boolean
  /** The line may change globbing (`shopt`, `GLOBIGNORE`): `*` may then match `.agentic-qe`. */
  dotglob: boolean
  readonly root: string | undefined
  /** Shell variables the line set (`F=...`, `for f in ...`, `read f`), each to the values it can hold. */
  readonly vars: Map<string, readonly string[]>
  /** How deep in `bash -c`/`eval`/heredoc nesting this line is. */
  readonly depth: number
  /** Judges a nested shell command line (`bash -c "..."`, `.shell ...`) under this context. */
  readonly bash: (command: string, ctx: Ctx) => string | undefined
  /** What a `$(...)`/backtick substitution may expand to (producers.ts), cached per inner text. */
  readonly subst: (inner: string, ctx: Ctx) => readonly string[]
  /** What `read` receives from a `< <(...)` on the line, when that may be the store. */
  readFed: readonly string[] | undefined
  /** Judges a PowerShell command line (`pwsh -c ...` from the Bash tool) under this context. */
  readonly pwsh: (command: string, ctx: Ctx) => string | undefined
}

/** How a word touches learning data under this context, or undefined. */
export const kindOf = (word: string, ctx: Ctx): ProtectedKind | undefined => protectedKind(word.replace(EXTGLOB, '*'), ctx.inAqe, ctx.dotglob)

/** An extglob group (`@(qe)`, `!(x)`, `+(a|b)`): read as `*`, which it may match. */
const EXTGLOB = /[@!+*?]\([^()]*\)/g

export const isData = (w: string, ctx: Ctx): boolean => kindOf(w, ctx) !== undefined

export const isDataFileOrGlob = (w: string, ctx: Ctx): boolean => {
  const k = kindOf(w, ctx)
  return k === 'file' || k === 'glob'
}

/** Results one word may expand to before its expansions are read as `*` instead. */
export const WORD_BUDGET = 256

/** A `$` expansion's alternatives: one of these values stands in its place. */
type Unit = readonly string[]

/** The index of the bracket closing the one at `open` (`(`/`{`), or -1. */
function matching(w: string, open: number, o: string, c: string): number {
  let depth = 0
  for (let i = open; i < w.length; i++) {
    if (w[i] === o) depth++
    else if (w[i] === c && --depth === 0) return i
  }
  return -1
}

/** `${...}`'s alternatives: a known variable's values, a default word or `*`; anything unmodelled is `*`. */
function braceParam(inner: string, vars: ReadonlyMap<string, readonly string[]>, depth: number): Unit {
  const name = /^[A-Za-z_][A-Za-z0-9_]*$/.test(inner) ? inner : undefined
  if (name !== undefined) return vars.get(name) ?? ['*']
  // `${arr[@]}`, `${arr[*]}`, `${arr[0]}`, slices `${arr[@]:1}`: the array's values (an array binding holds every element).
  const element = /^([A-Za-z_][A-Za-z0-9_]*)\[[^\]]*\](:[^}]*)?$/.exec(inner)
  if (element !== null) return vars.get(element[1] as string) ?? ['*']
  const op = /^([A-Za-z_][A-Za-z0-9_]*)(:?[-=?+])(.*)$/s.exec(inner)
  if (op === null || depth > 8) return ['*']
  const known = vars.get(op[1] as string)
  const word = loose(op[3] as string, depth + 1)
  if ((op[2] as string).endsWith('+')) return [word, '']
  return [...(known ?? []), word, '*']
}

/** Resolves a substitution's inner text to what it may expand to; without one, every substitution is `*`. */
export type Subst = (inner: string) => readonly string[]

/** Splits a word into literal text and `$` expansions (unknown ones as `*`). */
function units(word: string, vars: ReadonlyMap<string, readonly string[]>, depth = 0, subst?: Subst): Array<string | Unit> {
  const out: Array<string | Unit> = []
  let lit = ''
  for (let i = 0; i < word.length; i++) {
    const c = word[i] as string
    const n = word[i + 1]
    let unit: Unit | undefined
    let end = i
    if (c === '`') {
      const close = word.indexOf('`', i + 1)
      end = close === -1 ? word.length - 1 : close
      unit = subst === undefined ? ['*'] : subst(word.slice(i + 1, end))
    } else if (c === '$' && n === '(') {
      const close = matching(word, i + 1, '(', ')')
      end = close === -1 ? word.length - 1 : close
      unit = subst === undefined ? ['*'] : subst(word.slice(i + 2, close === -1 ? word.length : close))
    } else if (c === '$' && n === '{') {
      const close = matching(word, i + 1, '{', '}')
      end = close === -1 ? word.length - 1 : close
      unit = braceParam(word.slice(i + 2, close === -1 ? word.length : close), vars, depth)
    } else if (c === '$' && n !== undefined && /[A-Za-z_]/.test(n)) {
      const m = /^[A-Za-z_][A-Za-z0-9_]*/.exec(word.slice(i + 1, i + 257)) as RegExpExecArray
      end = i + m[0].length
      unit = vars.get(m[0]) ?? ['*']
    } else if (c === '$' && n !== undefined && /[0-9@*#?$!-]/.test(n)) {
      end = i + 1
      unit = ['*']
    }
    if (unit === undefined) lit += c
    else {
      if (lit !== '') out.push(lit)
      lit = ''
      out.push(unit)
      i = end
    }
  }
  if (lit !== '') out.push(lit)
  return out
}

/** A word with every `$` expansion read as `*`: what it can always match. */
const loose = (word: string, depth = 0): string =>
  units(word, new Map(), depth)
    .map(u => (typeof u === 'string' ? u : '*'))
    .join('')

/**
 * A word as the shell may expand it: each known variable by the values it can
 * hold, every other `$NAME`, `${...}`, `$@`, `$(...)` and backtick as `*`
 * (unknown text can be anything), `${X:-w}` as `w` or `*`. Past `budget`
 * results the whole word is read loose, every expansion as `*`.
 */
export function expandVars(word: string, vars: ReadonlyMap<string, readonly string[]>, budget = WORD_BUDGET, subst?: Subst): string[] {
  if (!word.includes('$') && !word.includes('`')) return [word]
  const parts = units(word, vars, 0, subst)
  let count = 1
  let length = 0
  for (const p of parts) {
    if (typeof p === 'string') length += p.length
    else {
      count *= Math.max(1, p.length)
      // A loop, not Math.max(...spread): a unit may hold more values than the call stack takes.
      length += p.reduce((m, v) => Math.max(m, v.length), 0)
    }
  }
  // Too many results, or too long: read loose, but keep any alternative that names the store as a word of its own.
  if (count > budget || length > MAX_PATH) {
    const named = parts.flatMap(p => (typeof p === 'string' ? [] : p.filter(v => /agentic/i.test(v))))
    return [loose(word), ...new Set(named)]
  }
  let out = ['']
  for (const p of parts) out = typeof p === 'string' ? out.map(o => o + p) : out.flatMap(o => p.map(v => o + v))
  return out
}

/** A segment's words as the shell expands them: braces (unquoted ones only), then `$` expansions. */
export function expandWords(seg: Segment, ctx: Ctx): string[] {
  // Most words hold nothing to expand: no `$`, backtick or brace.
  if (!seg.words.some(w => /[$`{]/.test(w))) return [...seg.words]
  return seg.words.flatMap((w, i) => {
    const ex = seg.expandable[i] ?? w
    const braced = ex.includes('{') ? expandBraces(ex).map(unmask) : [w]
    const budget = Math.max(1, Math.floor(WORD_BUDGET / braced.length))
    return braced.flatMap(b => expandVars(b, ctx.vars, budget, inner => ctx.subst(inner, ctx)))
  })
}

/**
 * Words inside a script or SQL text that could be paths: split at quotes,
 * whitespace and punctuation, so `rmSync('.agentic-qe', {...})`,
 * `os.path.join('.agentic-qe','memory.db')` and `'${root}/.agentic-qe/memory.db'` each yield the path.
 */
export const pathTokens = (text: string): string[] => text.split(/[\s'"`,;(){}+<>|&=$]+/).filter(t => t !== '')

/** Whether a script or SQL text names learning data (the directory counts). */
export const textNamesData = (text: string, ctx: Ctx): boolean => pathTokens(text).some(t => isData(t, ctx))

/** Whether a script or SQL text names a learning-data file or glob (the directory alone does not). */
export const textNamesDataFile = (text: string, ctx: Ctx): boolean => pathTokens(text).some(t => isDataFileOrGlob(t, ctx))

files.hooks/powershell.ts:
/**
 * The guard's reading of a PowerShell tool command: Remove-Item, Move-Item,
 * Copy-Item, Set-Content, New-Item -Force and friends (and their aliases) on
 * learning data, `>` redirects, .NET file APIs, `cmd /c`, `Start-Process`,
 * `Invoke-Expression`/`iex` and `& { ... }` script blocks, and pipelines where
 * an earlier stage lists the store (`gci .agentic-qe *.db | Remove-Item`).
 * Anything else in a stage (sqlite3, git, python -c, ...) is read by the
 * shell rules. Pure: no `$`.
 */
import { holdsAqe } from './commands'
import { isData, isDataFileOrGlob, kindOf, textNamesData, type Ctx } from './context'
import { DATA_FILE, baseName, globMatches, globReachesData, underAqe } from './paths'
import { assignment, foreachOf, hasUnknownVar, rhsValues, substitute, type PsVars } from './psvars'

const DELETE = new Set(['remove-item', 'rm', 'del', 'erase', 'rd', 'rmdir', 'ri'])
const MOVE = new Set(['move-item', 'mv', 'move', 'mi'])
const COPY = new Set(['copy-item', 'cp', 'copy', 'cpi', 'cpp'])
const RENAME = new Set(['rename-item', 'ren', 'rni'])
const WRITE = new Set(['set-content', 'sc', 'clear-content', 'clc', 'out-file', 'add-content', 'ac', 'tee-object', 'tee'])
const CREATE = new Set(['new-item', 'ni'])
const CD = new Set(['cd', 'set-location', 'sl', 'chdir', 'pushd', 'push-location'])
const LIST = new Set(['get-childitem', 'gci', 'ls', 'dir'])
const EXPR = new Set(['invoke-expression', 'iex'])
const START = new Set(['start-process', 'saps', 'start'])
const PWSH = /^(pwsh|powershell)(\.exe)?$/
/** A downstream stage that destroys what is piped to it. */
const CONSUMES = /(^|[\s{;(])(remove-item|ri|rm|del|erase|rd|rmdir|move-item|mv|move|mi|clear-content|clc|set-content|sc|rename-item|ren|rni)(?=$|[\s;})])|\.delete\s*\(/i
/** .NET file APIs that delete, move or overwrite. */
const DOTNET = /\[(System\.)?IO\.(File|Directory|FileInfo|DirectoryInfo)\]::(Delete|Move|Copy|Replace|WriteAll\w*|AppendAll\w*|Create\w*|Open\w*)\b|\.Delete\s*\(/i
/** Names and extensions of the store's files and directory, for literal Where-Object filters. */
const STORE_NAMES = ['memory.db', 'memory.db-wal', 'memory.db-shm', 'memory.db-journal', 'brain.rvf', '.agentic-qe']
const STORE_EXTENSIONS = ['.db', '.db-wal', '.db-shm', '.db-journal', '.rvf', '.agentic-qe']
/** A `(...)`, `@(...)` or `$(...)` group inside a stage (one level of nesting). */
const GROUP = /[@$]?\(((?:[^()]|\([^()]*\))*)\)/g
/** `$x.Delete(...)` / `$x.MoveTo(...)` on a variable. */
const METHOD_ON_VAR = /\$\{?([A-Za-z_]\w*)\}?\.(delete|moveto)\s*\(/gi

/**
 * Whether a stage is a Where-Object filter that cannot pass a store file: a pure conjunction
 * (no `-or`, `-xor`, `-not`, `!`, `-ne`, `-notlike`, `-notmatch`) with at least one positive
 * literal `-eq`/`-like` on Name or Extension that cannot match a store file or `.agentic-qe`
 * (`Where-Object Extension -eq '.tmp'`, `{ $_.Extension -eq '.tmp' -and $_.Length -gt 0 }`).
 */
function narrowsAwayFromStore(stage: string): boolean {
  if (!/^\s*(where-object|where|\?)(\s|\{|$)/i.test(stage)) return false
  if (/-[ic]?(or|xor|not|ne|notlike|notmatch)\b|!/i.test(stage)) return false
  // A literal: single-quoted (where `$` is literal), or double-quoted without `$` (no expansion).
  const tests = /(?:\$_\.)?\b(name|extension)\s+-[ic]?(eq|like)\s+(?:'([^']*)'|"([^"$]*)")/gi
  for (const m of stage.matchAll(tests)) {
    const candidates = (m[1] as string).toLowerCase() === 'name' ? STORE_NAMES : STORE_EXTENSIONS
    const literal = (m[3] ?? m[4]) as string
    const misses = (m[2] as string).toLowerCase() === 'eq' ? candidates.every(c => c.toLowerCase() !== literal.toLowerCase()) : candidates.every(c => !globMatches(literal, c))
    if (misses) return true
  }
  return false
}

/** How deep `iex`, `& { }` and `Start-Process` text is followed before naming the store at all is refused. */
const MAX_DEPTH = 6

/** Splits at top-level separators (outside quotes, braces and parentheses; backtick escapes). */
function splitTop(command: string, at: (c: string, next: string | undefined) => boolean): string[] {
  const out: string[] = []
  let cur = ''
  let quote: string | undefined
  let depth = 0
  for (let i = 0; i < command.length; i++) {
    const c = command[i] as string
    if (quote !== undefined) {
      if (c === quote) quote = undefined
      cur += c
    } else if (c === '`') {
      cur += command[i + 1] ?? ''
      i++
    } else if (c === "'" || c === '"') {
      quote = c
      cur += c
    } else if (c === '{' || c === '(') {
      depth++
      cur += c
    } else if (c === '}' || c === ')') {
      depth = Math.max(0, depth - 1)
      cur += c
    } else if (depth === 0 && at(c, command[i + 1])) {
      if (command[i + 1] === c) i++
      out.push(cur)
      cur = ''
    } else cur += c
  }
  out.push(cur)
  return out.map(s => s.trim()).filter(s => s !== '')
}

const statements = (command: string): string[] => splitTop(command, (c, n) => c === ';' || c === '\n' || (c === '&' && n === '&') || (c === '|' && n === '|'))
const stages = (statement: string): string[] => splitTop(statement, (c, n) => c === '|' && n !== '|')

/** Words of one stage, quotes and grouping parentheses removed, backslashes kept (they are path separators here). */
const psWords = (seg: string): string[] =>
  [...seg.matchAll(/'([^']*)'|"([^"]*)"|(\S+)/g)]
    .map(m => m[1] ?? m[2] ?? m[3] ?? '')
    .map(w => w.replace(/^-\w+:(?=.)/, '').replace(/^[@$]?\(+|\)+$/g, ''))

/** Redirect targets (`>`, `>>`, `*>`, `2>`). */
const psRedirects = (seg: string): string[] => [...seg.matchAll(/(?:^|[^-])[*\d]?>{1,2}\s*(['"]?)([^\s'"]+)\1/g)].map(m => m[2] ?? '')

/** The value of a named parameter (`-Destination X`, `-Path X`), case-insensitively. */
function param(ws: readonly string[], ...names: string[]): string | undefined {
  const i = ws.findIndex(w => names.some(n => w.toLowerCase() === `-${n}`))
  return i === -1 ? undefined : ws[i + 1]
}

/** Whether a switch is given, by any unambiguous prefix PowerShell accepts (`-r`, `-rec`, `-Recurse`). */
const hasSwitch = (ws: readonly string[], name: string, min: number): boolean =>
  ws.some(w => w.startsWith('-') && w.length - 1 >= min && name.startsWith(w.slice(1).toLowerCase()))

/** Operands: words that are not `-Param` names (a parameter's value counts as an operand). */
const operands = (ws: readonly string[]): string[] => ws.filter(w => !/^-[A-Za-z]/.test(w))

/** The verb of a stage (past a leading `&`/`.` call operator) and its argument words. */
function verbOf(seg: string): { verb: string; args: string[] } {
  const ws = psWords(seg)
  const call = ws[0] === '&' || ws[0] === '.'
  return { verb: baseName(call ? (ws[1] ?? '') : (ws[0] ?? '')).toLowerCase(), args: call ? ws.slice(2) : ws.slice(1) }
}

/**
 * Whether a stage hands the store to the next one: it names it; it lists recursively from
 * where it may be; it lists hidden items (`-Force`, `-Hidden`) for a recursive delete; or it
 * lists inside `.agentic-qe` (after `sl .agentic-qe`).
 */
function feedsStore(seg: string, ctx: Ctx, recursiveConsumer = false): boolean {
  if (textNamesData(seg.replace(/\\/g, '/'), ctx)) return true
  const { verb, args } = verbOf(seg)
  if (!LIST.has(verb)) return false
  const hidden = hasSwitch(args, 'force', 2) || hasSwitch(args, 'hidden', 2)
  if (!hasSwitch(args, 'recurse', 1) && !(hidden && recursiveConsumer) && !ctx.inAqe) return false
  const ops = operands(args)
  // The listing root: -Path, or the first operand unless it is a bare pattern (`ls -r *.db` lists from here).
  const first = ops[0]
  const path = param(args, 'path', 'literalpath') ?? (first !== undefined && !(/[*?]/.test(first) && !/[\\/]/.test(first)) ? first : undefined)
  if (path !== undefined && !holdsAqe(path.replace(/\\/g, '/'), ctx) && !underAqe(path.replace(/\\/g, '/'), ctx.inAqe)) return false
  const patterns = [param(args, 'filter'), param(args, 'include'), ...ops.filter(o => o !== path)].filter((p): p is string => p !== undefined)
  return patterns.length === 0 || patterns.some(p => globReachesData(baseName(p)) || globMatches(baseName(p), '.agentic-qe'))
}

function judgePsSegment(seg: string, ctx: Ctx, depth: number): string | undefined {
  const redirect = psRedirects(seg).find(t => isDataFileOrGlob(t, ctx))
  if (redirect !== undefined) return `a PowerShell redirect overwrites ${redirect}`
  // A .NET file API on the store, or on an argument the guard cannot resolve (an unknown `$p`, read as `*`).
  if (DOTNET.test(seg) && (textNamesData(seg.replace(/\\/g, '/'), ctx) || /\(\s*['"]?\*/.test(seg))) return 'a .NET file API deletes or overwrites AQE learning data'
  // A script block (`& { ... }`, `ForEach-Object { ... }`) is read as PowerShell of its own.
  for (const block of seg.matchAll(/\{([^{}]*)\}/g)) {
    const what = judgePowerShell(block[1] ?? '', ctx, depth + 1)
    if (what !== undefined) return what
  }
  const { verb, args } = verbOf(seg)
  const ops = operands(args)
  if (CD.has(verb)) {
    const t = ops[0]
    if (t !== undefined) ctx.inAqe = underAqe(t, ctx.inAqe) && !t.startsWith('..')
    return undefined
  }
  if (verb === 'cmd' || verb === 'cmd.exe') {
    const c = args.findIndex(a => /^\/[ck]$/i.test(a))
    return c === -1 ? undefined : judgePowerShell(args.slice(c + 1).join(' '), ctx, depth + 1)
  }
  if (EXPR.has(verb)) return judgePowerShell(ops.join(' '), ctx, depth + 1)
  if (START.has(verb)) {
    // `-ArgumentList '/c','rd','/s','/q','.agentic-qe'` is a comma list; `'-Command ...'` one string.
    const listed = /-(?:argumentlist|args)\s+((?:(?:'[^']*'|"[^"]*"|[^\s,'"]+)\s*,\s*)*(?:'[^']*'|"[^"]*"|[^\s,'"]+))/i.exec(seg)?.[1]
    const list = listed === undefined ? ops.slice(1).join(' ') : listed.split(/\s*,\s*/).map(a => a.replace(/^(['"])([\s\S]*)\1$/, '$2')).join(' ')
    const file = param(args, 'filepath') ?? ops[0] ?? ''
    return judgePowerShell(`${file} ${list}`, ctx, depth + 1)
  }
  if (PWSH.test(verb)) {
    const c = args.findIndex(a => /^-(c|command|encodedcommand|ec|e)$/i.test(a))
    if (c === -1) return undefined
    if (/^-(encodedcommand|ec|e)$/i.test(args[c] as string)) return `\`${verb} -EncodedCommand\` runs a script the guard cannot read`
    return judgePowerShell(args.slice(c + 1).join(' '), ctx, depth + 1)
  }
  if (DELETE.has(verb)) {
    const hit = ops.find(a => isData(a, ctx))
    if (hit !== undefined) return `\`${verb}\` on ${hit}`
    return textNamesData(seg.replace(/\\/g, '/'), ctx) ? `\`${verb}\` on what names AQE learning data` : undefined
  }
  if (MOVE.has(verb) || RENAME.has(verb)) {
    const dest = param(args, 'destination', 'newname') ?? (ops.length > 1 ? ops[ops.length - 1] : undefined)
    const src = ops.filter(o => o !== dest)
    const moved = src.find(a => isData(a, ctx))
    if (moved !== undefined) return `\`${verb}\` moves ${moved} away`
    return dest !== undefined && isDataFileOrGlob(dest, ctx) ? `\`${verb}\` overwrites ${dest}` : undefined
  }
  if (COPY.has(verb)) {
    const dest = param(args, 'destination') ?? ops[ops.length - 1]
    if (dest === undefined || ops.length < 2) return undefined
    const k = kindOf(dest, ctx)
    const src = ops.filter(o => o !== dest)
    if (k === 'file' || k === 'glob' || (k === 'dir' && src.some(s => DATA_FILE.test(baseName(s))))) return `\`${verb}\` overwrites ${dest}`
    return undefined
  }
  if (WRITE.has(verb)) {
    const target = param(args, 'path', 'literalpath', 'filepath') ?? ops.find(o => isDataFileOrGlob(o, ctx)) ?? ops[0]
    return target !== undefined && isDataFileOrGlob(target, ctx) ? `\`${verb}\` writes ${target}` : undefined
  }
  // New-Item -Force replaces an existing file with an empty one.
  if (CREATE.has(verb) && hasSwitch(args, 'force', 2)) {
    const hit = ops.find(o => isDataFileOrGlob(o, ctx))
    return hit === undefined ? undefined : `\`${verb} -Force\` replaces ${hit}`
  }
  // Not a PowerShell file cmdlet: read it as a shell command (sqlite3, git, python -c, bash -c ...).
  return ctx.bash(seg.replace(/\\/g, '/'), ctx)
}

/** The refusal reason for a PowerShell command line, or undefined. Variables bound on the line are read through. */
export function judgePowerShell(command: string, ctx: Ctx, depth = 0, vars: PsVars = new Map()): string | undefined {
  if (depth > MAX_DEPTH) return /agentic/i.test(command) ? 'PowerShell nested too deeply to read names learning data' : undefined
  for (const raw of statements(command)) {
    // `iex` of text holding a variable the guard cannot resolve: it cannot read what runs.
    if (/^(iex|invoke-expression)\b/i.test(raw.trim()) && hasUnknownVar(raw, vars)) return '`Invoke-Expression` runs text the guard cannot read'
    const loop = foreachOf(raw)
    if (loop !== undefined) vars.set(loop.name, rhsValues(substitute(loop.source, vars), ctx, t => feedsStore(t, ctx, true)))
    // `$db.Delete()`, `$f.MoveTo(...)` on a variable that holds the store or a listing of it.
    for (const m of raw.matchAll(METHOD_ON_VAR)) {
      if ((vars.get((m[1] as string).toLowerCase()) ?? []).some(v => isData(v.replace(/\\/g, '/'), ctx))) return `\`$${m[1] as string}.${m[2] as string}()\` on AQE learning data`
    }
    const bound = assignment(raw)
    const statement = substitute(bound === undefined ? raw : bound.rhs, vars)
    const parts = stages(statement)
    for (let i = 0; i < parts.length; i++) {
      const part = parts[i] as string
      const what = judgePsSegment(part, ctx, depth)
      if (what !== undefined) return what
      const recursive = hasSwitch(verbOf(part).args, 'recurse', 1)
      if (CONSUMES.test(part)) {
        // A `(...)`/`@(...)`/`$(...)` argument is a stage of its own (`Remove-Item (gci -r -Filter *.db)`).
        for (const g of part.matchAll(GROUP)) if (feedsStore(g[1] as string, ctx, recursive)) return `\`${verbOf(part).verb}\` is handed AQE learning data by \`(${(g[1] as string).trim()})\``
        // Data flow: a destroying stage fed by one that names, lists recursively or lists hidden items of the store,
        // unless a literal Where-Object filter in between cannot pass a store file.
        const fed = parts.slice(0, i).some((up, j) => feedsStore(up, ctx, recursive) && !parts.slice(j + 1, i).some(narrowsAwayFromStore))
        if (i > 0 && fed) return `a PowerShell pipeline feeds AQE learning data to \`${verbOf(part).verb}\``
      }
      // `-OutVariable dbs` / `-ov dbs`: the variable holds what this stage outputs.
      const ov = /-(?:outvariable|ov)\s+\+?([A-Za-z_]\w*)/i.exec(part)
      if (ov !== null) vars.set((ov[1] as string).toLowerCase(), rhsValues(part, ctx, t => feedsStore(t, ctx, true)))
    }
    if (bound !== undefined) {
      const values = rhsValues(statement, ctx, t => feedsStore(t, ctx, true))
      vars.set(bound.name, bound.append ? [...(vars.get(bound.name) ?? []), ...values] : values)
    }
  }
  return undefined
}

files.hooks/producers.ts:
/**
 * Commands whose output becomes other commands' arguments: `$(...)`/backtick
 * substitutions, `< <(...)` feeding `read`, and pipeline stages feeding
 * `xargs`/`read`. The guard cannot see their output, so it decides what that
 * output may be: a substitution that names the store yields those paths; one
 * that lists files which may include the store (`find`, `ls -A`, `git
 * ls-files -o`), or whose output is opaque (`cat list`, `base64 -d`), may
 * yield the store itself. Only known-harmless producers (`date`, `pwd`,
 * `find . -name '*.tmp'`) read as plain `*`. Pure: no `$`.
 */
import { holdsAqe, isVerb, verbName } from './commands'
import { isData, pathTokens, textNamesData, type Ctx } from './context'
import { asDeleting, judgeFind } from './find'
import { commandStart, isOption, parse, type Segment } from './shell'

/** What the output of a command that may list or emit the store can be (`*` first, so a destination slot sees the store). */
export const DATA_ALTS: readonly string[] = ['*', '.agentic-qe', '.agentic-qe/memory.db']

/** Commands whose output is never a path the guard cares about. */
const HARMLESS = new Set(['date', 'pwd', 'mktemp', 'basename', 'dirname', 'realpath', 'readlink', 'whoami', 'id', 'uname', 'hostname', 'nproc', 'seq', 'true', 'false', 'tty', 'getconf', 'echo', 'printf', 'wc', 'which', 'whereis'])
/** Shell-setup generators whose output `eval` runs (`eval "$(ssh-agent -s)"`). */
const ENV_INIT = new Set(['ssh-agent', 'direnv', 'pyenv', 'rbenv', 'nodenv', 'fnm', 'brew', 'conda', 'zoxide', 'starship', 'mise', 'rtx', 'gpg-agent', 'dircolors', 'keychain'])
/** Filters that only select or reorder lines they are piped. */
const FILTERS = new Set(['head', 'tail', 'sort', 'uniq', 'grep', 'egrep', 'fgrep', 'wc', 'cut', 'tr'])
const GIT_READS = new Set(['rev-parse', 'describe', 'branch', 'log', 'show', 'diff', 'tag', 'config', 'remote', 'symbolic-ref', 'hash-object'])
/** Package-manager queries that print a cache or store directory (`npm config get cache`, `go env GOCACHE`). */
const TOOL_PATHS = /^(npm|yarn|pnpm|bun) (cache dir|config get|store path|root|bin|prefix)\b|^go env\b|^pip cache dir\b|^cargo metadata\b/

/** Command words that may list the store (`find`, `ls -A`, `dir`, `git ls-files -o`). */
const LISTERS = /(^|\/)(find|ls|dir|git)$/

type Verdict = 'harmless' | 'reaches' | 'opaque'

/** Whether one command's output may name the store: never, by listing it (`reaches`), or unknowably (`opaque`). */
function verdictOf(words: readonly string[], ctx: Ctx, piped: boolean): Verdict {
  const at = commandStart(words, isVerb)
  const verb = verbName(words[at] ?? '')
  const args = words.slice(at + 1)
  const operands = args.filter(a => !isOption(a))
  if (verb === '') return 'harmless'
  // `command -v x` / `type -P x` print where a command lives.
  if ((words[0] === 'command' && /^-[vV]$/.test(words[1] ?? '')) || (words[0] === 'type' && /^-[pP]+$/.test(words[1] ?? ''))) return 'harmless'
  if (TOOL_PATHS.test(words.slice(at).join(' '))) return 'harmless'
  if (verb === 'find') return judgeFind(asDeleting(args), ctx) === undefined ? 'harmless' : 'reaches'
  if (verb === 'ls' || verb === 'dir') {
    const all = args.some(a => /^-[A-Za-z]*[aAf]/.test(a) || a === '--all' || a === '--almost-all')
    return all && (operands.length === 0 || operands.some(o => holdsAqe(o, ctx))) ? 'reaches' : 'harmless'
  }
  if (verb === 'git') {
    const sub = operands[0] ?? ''
    if (sub === 'ls-files') return args.some(a => /^-[A-Za-z]*[oi]/.test(a) || a === '--others' || a === '--ignored') ? 'reaches' : 'harmless'
    // `git status` prints untracked (`??`) and, with --ignored, ignored paths: the store among them.
    if (sub === 'status') return 'reaches'
    return GIT_READS.has(sub) ? 'harmless' : 'opaque'
  }
  // echo/printf print their arguments: harmless unless an unknown variable feeds them.
  if (HARMLESS.has(verb)) return (verb === 'echo' || verb === 'printf') && args.some(a => /[$][A-Za-z_{@*0-9]/.test(a)) ? 'opaque' : 'harmless'
  if (FILTERS.has(verb) && (piped || operands.length === 0)) return 'harmless'
  return 'opaque'
}

/** The worst verdict over every command a text runs (nested substitutions included). */
function verdictOfText(text: string, ctx: Ctx): Verdict {
  let worst: Verdict = 'harmless'
  for (const seg of parse(text)) {
    if (seg.dropped !== undefined) return 'opaque'
    // `$(< file)` prints a file the guard cannot see, as `$(cat file)` does.
    if (seg.words.length === 0 && seg.redirects.some(r => r.op === '<')) return 'opaque'
    const v = verdictOf(seg.words, ctx, seg.piped)
    if (v === 'opaque') return 'opaque'
    if (v === 'reaches') worst = 'reaches'
  }
  return worst
}

/**
 * What a `$(...)`/backtick substitution may expand to. Naming the store: those paths (and `*`).
 * Listing files that may include it, or opaque: DATA_ALTS. Harmless: `*`.
 */
export function substitutionAlts(inner: string, ctx: Ctx): readonly string[] {
  if (inner.trim() === '') return ['']
  if (textNamesData(inner, ctx)) {
    const named = pathTokens(inner).filter(t => isData(t, ctx))
    return ['*', ...new Set(named)]
  }
  if (ctx.depth > 6) return DATA_ALTS
  return verdictOfText(inner, ctx) === 'harmless' ? ['*'] : DATA_ALTS
}

/** Whether `eval`/`bash -c` would run a script the guard cannot read: one that is wholly an expansion (`"$CMD"`, `"$(curl ... | base64 -d)"`). */
export function opaqueScript(raw: string, ctx: Ctx): boolean {
  const word = raw.trim()
  const sub = /^\$\(([\s\S]*)\)$|^`([\s\S]*)`$/.exec(word)
  if (sub !== null) {
    const inner = sub[1] ?? sub[2] ?? ''
    const first = parse(inner)[0]
    if (first !== undefined && ENV_INIT.has(verbName(first.words[commandStart(first.words, isVerb)] ?? ''))) return false
    return verdictOfText(inner, ctx) !== 'harmless' || textNamesData(inner, ctx)
  }
  const v = /^\$\{?([A-Za-z_][A-Za-z0-9_]*)\}?$/.exec(word)
  return v !== null && !ctx.vars.has(v[1] as string)
}

/** Whether an earlier stage of this pipeline lists files that may include the store (`find . -name '*.db' | xargs rm`, `git ls-files -oi | xargs rm`). */
export function fedByProducer(seg: Segment, ctx: Ctx): boolean {
  // Only these can list the store; most stages are skipped without being read.
  return seg.stages.some((stage, i) => stage.some(w => LISTERS.test(w)) && verdictOf(stage, ctx, i > 0) === 'reaches')
}

