  if (group !== undefined && !literals(group)) return rhsValues(group, ctx, feeds)
  const array = group ?? (/^(['"][^'"]*['"]\s*,\s*)+['"][^'"]*['"]$/.test(t) ? t : undefined)
  if (array !== undefined) return array.split(',').map(unquote).filter(v => v !== '')
